// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BillQuery) predicate.BillQuery {
	return predicate.BillQuery(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BillQuery) predicate.BillQuery {
	return predicate.BillQuery(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BillQuery) predicate.BillQuery {
	return predicate.BillQuery(sql.NotPredicates(p))
}
